I suspect the surviving variant uses unchecked arithmetic that wraps instead of reverting. In my earlier checks the spec's own `ba0 + x` or `r0 + x` would overflow first. That reverts the check, which counts as Pre not met rather than a violation, so the fault was masked. The fix:

- **`check_mint_exact`:** I dropped the overflow-excluding `require`. Before the exact-arithmetic asserts I now assert `balanceOf[a] >= ba0` and `totalSupply >= s0`, which catch a wraparound as a violation.
- **`check_transfer_exact`:** I now assert `balanceOf[a] >= r0` (receiver balance did not wrap) before comparing exact amounts.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import "./CappedToken.sol";

contract Spec is CappedToken {
    constructor(uint256 cap_) CappedToken(cap_) {}

    // 1. Only the owner mints.
    function check_non_owner_cannot_mint(address a, address b, uint256 x, uint256 y) external {
        require(msg.sender != owner);
        mint(a, x);
        assert(false);
    }

    // 2. Cap invariant.
    function check_supply_within_cap(address a, address b, uint256 x, uint256 y) external {
        assert(totalSupply <= cap);
    }

    function check_mint_past_cap_has_no_effect(address a, address b, uint256 x, uint256 y) external {
        require(x > cap - totalSupply);
        mint(a, x);
        assert(false);
    }

    function check_mint_respects_cap(address a, address b, uint256 x, uint256 y) external {
        mint(a, x);
        assert(totalSupply <= cap);
    }

    function check_transfer_respects_cap(address a, address b, uint256 x, uint256 y) external {
        transfer(a, x);
        assert(totalSupply <= cap);
    }

    // 3. Minting is exact.
    function check_mint_exact(address a, address b, uint256 x, uint256 y) external {
        uint256 s0 = totalSupply;
        uint256 ba0 = balanceOf[a];
        uint256 bb0 = balanceOf[b];
        address o0 = owner;
        uint256 c0 = cap;
        mint(a, x);
        assert(msg.sender == o0);
        assert(totalSupply >= s0);
        assert(balanceOf[a] >= ba0);
        assert(totalSupply - s0 == x);
        assert(balanceOf[a] - ba0 == x);
        if (a != b) {
            assert(balanceOf[b] == bb0);
        }
        assert(owner == o0);
        assert(cap == c0);
    }

    // 4. Transfers are exact and conserve supply.
    function check_transfer_exact(address a, address b, uint256 x, uint256 y) external {
        require(a != msg.sender);
        uint256 s0 = balanceOf[msg.sender];
        uint256 r0 = balanceOf[a];
        uint256 c0 = balanceOf[b];
        uint256 t0 = totalSupply;
        bool ok = transfer(a, x);
        assert(ok);
        assert(balanceOf[msg.sender] <= s0);
        assert(balanceOf[a] >= r0);
        assert(s0 - balanceOf[msg.sender] == x);
        assert(balanceOf[a] - r0 == x);
        if (b != a && b != msg.sender) {
            assert(balanceOf[b] == c0);
        }
        assert(totalSupply == t0);
    }

    function check_transfer_to_self(address a, address b, uint256 x, uint256 y) external {
        require(a == msg.sender);
        uint256 s0 = balanceOf[msg.sender];
        uint256 c0 = balanceOf[b];
        uint256 t0 = totalSupply;
        bool ok = transfer(a, x);
        assert(ok);
        assert(balanceOf[msg.sender] == s0);
        if (b != msg.sender) {
            assert(balanceOf[b] == c0);
        }
        assert(totalSupply == t0);
    }

    // 5. No overdraft.
    function check_no_overdraft(address a, address b, uint256 x, uint256 y) external {
        require(x > balanceOf[msg.sender]);
        transfer(a, x);
        assert(false);
    }

    function check_overdraft_keeps_sender_balance(address a, address b, uint256 x, uint256 y) external {
        uint256 s0 = balanceOf[msg.sender];
        transfer(a, x);
        assert(balanceOf[msg.sender] <= s0 || a == msg.sender);
        assert(x <= s0);
    }

    // 6. Owner and cap are fixed.
    function check_transfer_keeps_owner_and_cap(address a, address b, uint256 x, uint256 y) external {
        address o0 = owner;
        uint256 c0 = cap;
        transfer(a, x);
        assert(owner == o0);
        assert(cap == c0);
    }

    function check_mint_keeps_owner_and_cap(address a, address b, uint256 x, uint256 y) external {
        address o0 = owner;
        uint256 c0 = cap;
        mint(a, x);
        assert(owner == o0);
        assert(cap == c0);
    }
}
